import React, { useState, useEffect } from 'react';
import ModalForm from '../../components/ModalForm';

function OrdersList() {
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [selectedOrder, setSelectedOrder] = useState(null);
  const [showModal, setShowModal] = useState(false);

  const token = localStorage.getItem('token');

  const fetchOrders = async () => {
    try {
      const res = await fetch('http://localhost/api/comandes', {
        headers: { Authorization: `Bearer ${token}` }
      });
      const data = await res.json();
      setOrders(data.dades || []);
    } catch (err) {
      setError('Error al obtenir les comandes');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { fetchOrders(); }, []);

  const handleDelete = async (id) => {
    if (!window.confirm('Segur que vols eliminar aquesta comanda?')) return;
    try {
      const res = await fetch(`http://localhost/api/comandes/${id}`, {
        method: 'DELETE',
        headers: { Authorization: `Bearer ${token}` }
      });
      if (!res.ok) throw new Error('Error al eliminar');
      setOrders(orders.filter(o => o.id !== id));
    } catch (err) {
      alert(err.message);
    }
  };

  const handleEdit = (order) => {
    setSelectedOrder(order);
    setShowModal(true);
  };

  if (loading) return <p>Carregant comandes...</p>;
  if (error) return <p>{error}</p>;
  if (orders.length === 0) return <p>No hi ha comandes disponibles.</p>;

  return (
    <div>
      <button className="btn btn-success mb-3" onClick={() => { setSelectedOrder(null); setShowModal(true); }}>
        Crear Comanda
      </button>

      <div className="row">
        {orders.map(order => (
          <div key={order.id} className="col-md-6 mb-3">
            <div className="card h-100">
              <div className="card-body">
                <h5 className="card-title">Client: {order.client?.nom}</h5>
                <p className="card-text"><strong>Proveïdor:</strong> {order.proveidor?.nom}</p>
                <p className="card-text"><strong>Tipus:</strong> {order.tipus}</p>
                <p className="card-text"><strong>Data:</strong> {new Date(order.data).toLocaleDateString('ca-ES')}</p>
                <button className="btn btn-primary me-2" onClick={() => handleEdit(order)}>Editar</button>
                <button className="btn btn-danger" onClick={() => handleDelete(order.id)}>Eliminar</button>
              </div>
            </div>
          </div>
        ))}
      </div>

      {showModal && (
        <ModalForm
          entity="comandes"
          data={selectedOrder}
          onClose={() => { setShowModal(false); fetchOrders(); }}
        />
      )}
    </div>
  );
}

export default OrdersList;
